UPDATE lessons SET title='Year 4, Week 16, Lesson 2: Empathy role plays', data=json_patch(data,'{"child_mission":"Empathy role plays practise listening, naming feelings and offering support without taking over.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same idea to a new game or situation, then compare two choices for safety and inclusion.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nWhy ask whether someone wants ideas or listening first?\n\nFEEDBACK\nHelp should match need; unasked advice can feel dismissive.\n\nWATCH FOR\nForcing someone to talk is not empathy.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nRole-play four support scenes. Record which question helped. Pass allowed.\n\nWrite a short reflection naming one choice you changed and why. Any movement is optional, adult-supervised and can be done in a gentler way or described instead.","interactive_activities":null,"learning_area":"PDHPE","learning_intention":"Empathy role plays practise listening, naming feelings and offering support without taking over.","lesson_number":2,"lesson_role":"Practise and apply","materials":["Paper or typed answer space","Pencil","Clear, safe movement space with an adult nearby for any physical activity","Optional: soft ball, cushion or water bottle"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["PH2-RRS-01"],"parent_notes":"Parent: Marking guidance for the independent task: Role-play four support scenes. Record which question helped. Pass allowed. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: original example using empathy on new material; names a specific word, source or choice and explains its effect.\n\nParent: Written model 2: Sample error: Forcing someone to talk is not empathy.. Correction: Help should match need; unasked advice can feel dismissive.. Why it helps the audience is stated.\n\nParent: Likely misconception: Forcing someone to talk is not empathy. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating empathy on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with empathy, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Accept original work about empathy with a specific supporting detail. Reject copied model wording with no new material. / Accept a misconception, a correction, and a purpose-linked reason for empathy. Reject corrections that do not change the inaccurate idea..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"This matches the taught method for empathy. The other choices miss a key step or use a common mistake.","options":["Help should match need; unasked advice can feel dismissive","Forcing someone to talk is not empathy","A claim that names no evidence from the lesson material","A method that skips the key step taught in this lesson"],"question":"Why ask whether someone wants ideas or listening first?","type":"multiple_choice"},{"correct_index":2,"explanation":"This is the misconception to avoid for empathy; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Help should match need; unasked advice can feel dismissive","Careful use of role play and explain why it matters with clear evidence","Forcing someone to talk is not empathy","Empathy role plays practise listening, naming feelings and offering support without taking over"],"question":"Which statement is a common mistake when working with empathy?","type":"multiple_choice"},{"correct_index":1,"explanation":"Understanding is shown by new evidence and a named role play and explain why it matters, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Name role play and explain why it matters only, without linking it to empathy","Apply empathy to new material and name the role play and explain why it matters used","Repeat the worked example wording with no new evidence","Forcing someone to talk is not empathy"],"question":"Which response best applies empathy with new evidence?","type":"multiple_choice"},{"correct_index":1,"explanation":"The stronger choice uses safe, healthy or respectful choices appropriately for this lesson on empathy. The other choices miss a key step or use a common mistake.","options":["Forcing someone to talk is not empathy","Help should match need; unasked advice can feel dismissive","Choose the fastest option even when it ignores safety","Use a put-down and call it honesty"],"question":"Which response best uses safe, healthy or respectful choices for empathy?","type":"multiple_choice"},{"correct_index":3,"explanation":"Strong answers name specific evidence and what it shows. The other choices miss a key step or use a common mistake.","options":["Choose the fastest option even when it ignores safety","Use a put-down and call it honesty","Forcing someone to talk is not empathy","Name a body cue, safety rule or wellbeing strategy and say how it helps with empathy"],"question":"Which evidence move best supports a claim about empathy?","type":"multiple_choice"},{"correct_index":1,"explanation":"The stronger choice matches the taught idea (Empathy role plays practise listening, naming feelings and offering) with concrete detail. The other choices miss a key step or use a common mistake.","options":["Use a put-down and call it honesty","Example: listener nods, paraphrases, asks “Do you want ideas or just listening?”","Forcing someone to talk is not empathy","Choose the fastest option even when it ignores safety"],"question":"Which choice best applies this lesson idea about empathy?","type":"multiple_choice"},{"correct_index":3,"explanation":"Accuracy means checking evidence and honouring limits or protocols. The other choices miss a key step or use a common mistake.","options":["Invent missing details to make the answer sound complete","Ignore safety or cultural protocols to finish faster","Treat every claim as equally reliable without checking a source or cue","Check safety and fairness, include others, and explain the healthier choice"],"question":"Which action keeps safe, healthy or respectful choices accurate for empathy?","type":"multiple_choice"},{"correct_index":3,"explanation":"Independence requires a new example that still uses the taught skill. The other choices miss a key step or use a common mistake.","options":["Retype the worked example with no new example","Forcing someone to talk is not empathy","Name role play and explain why it matters only, with no linked example","Role-play four support scenes"],"question":"Which independent response best applies empathy to new material?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept original work about empathy with a specific supporting detail. Reject copied model wording with no new material.","question":"Produce a fresh example demonstrating empathy on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Sample: original example using empathy on new material; names a specific word, source or choice and explains its effect.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception, a correction, and a purpose-linked reason for empathy. Reject corrections that do not change the inaccurate idea.","question":"Name one likely error with empathy, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Sample error: Forcing someone to talk is not empathy.. Correction: Help should match need; unasked advice can feel dismissive.. Why it helps the audience is stated.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested. Share only what you feel comfortable sharing.","review_status":"unreviewed","seed_key":"s2-pdhpe-y4-w16-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA PDHPE alignment using catalogue outcome codes (PH2-*); content-point mapping remains pending human review. Physical activities are optional, adult-supervised and adaptable; no child is required to share personal details.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise empathy.","Read the mission before you start moving or deciding.","Keep your own safety and everyone''s inclusion in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your reasons with the feedback.","Adjust anything that does not keep everyone safe and included."],"learn":["Study how the first demonstration is built.","Point to the cue or rule that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore safety, consent or inclusion.","Prefer a reasoned, respectful choice over one that merely looks fun."],"submit":["Confirm that your reasons and reflection are both present.","Proofread names, steps and safety words.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked example.","Name one exact cue, rule or choice before you decide.","Think through the small prompt before opening the comparison."],"teach1":["Return to the example and list the key cues.","Say what each cue does for safety, health or friendship.","A final label alone is weaker than a stated reason."],"teach2":["Compare an unsafe or unkind choice with a better one.","Change the choice or strategy, not only the words.","Name the mistake you are repairing."],"teach3":["Choose a fresh place, game or situation that still uses the same skill.","Write one reason in your own words.","Do not retype the worked example as your answer."],"write":["Follow every part of the independent instructions.","Include original reasons and a short reflection.","Save work that shows the skill in a new situation."]},"subject":"Health, Wellbeing and Relationships","success_criteria":["I can use empathy with a specific example from this lesson.","I can identify role play and explain why it matters.","I can practise listen independently on a new prompt.","I can notice support needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":3,"explanation":"Empathy role plays practise listening, naming feelings and offering support without taking over. Supported choices follow the actual cues, rules and purpose of the task. Apply the lesson idea with evidence. The other choices miss a key step or use a common mistake.","options":["A choice unrelated to safety, health or respect","An answer copied without understanding","A guess with no reason","Empathy role plays practise listening, naming feelings and offering support without taking over"],"question":"Which choice best applies this lesson idea about empathy with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: listener nods, paraphrases, asks “Do you want ideas or just listening?”\n\nTRY FIRST\nWhy ask whether someone wants ideas or listening first?\n\nFEEDBACK\nHelp should match need; unasked advice can feel dismissive.","explain":"Empathy role plays practise listening, naming feelings and offering support without taking over.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Forcing someone to talk is not empathy. Change the choice or strategy, not just the wording.","title":"Understand and demonstrate","visual":[{"alt":"Empathy role plays.","caption":"Match help to need.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Listen</text><text x=\"28\" y=\"78\">paraphrase</text><text x=\"358\" y=\"42\">Ask</text><text x=\"358\" y=\"78\">ideas or listening</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which cue or rule matters most.","who":"pip"},{"text":"Name the cues, rules or choices that keep everyone safe and included before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this example: Example: listener nods, paraphrases, asks “Do you want ideas or just listening?” Then write your own reasons.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which cue or rule matters most.\nJuno: Name the cues, rules or choices that keep everyone safe and included before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this example: Example: listener nods, paraphrases, asks “Do you want ideas or just listening?” Then write your own reasons."}}]},{"check":{"correct_index":3,"explanation":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.","options":["A choice unrelated to safety, health or respect","An answer copied without understanding","A guess with no reason","Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or"],"question":"Which choice best applies this lesson idea about empathy with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: listener nods, paraphrases, asks “Do you want ideas or just listening?” Look at each cue, rule or choice that carries the idea.\n\nTRY FIRST\nList the key cues, rules or choices from the example and say what each one does for safety, health or relationships.\n\nFEEDBACK\nThe most useful reasoning names the cue, rule or strategy and the reason it helps, not only a label such as \"good\".","explain":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Writing only a final label without a reason does not show PDHPE thinking. Change the choice or strategy, not just the wording.","title":"Show the reasoning","visual":[{"alt":"Support practice.","caption":"Question helped.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Four scenes</text><text x=\"28\" y=\"78\">pass OK</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">force talking</text></g></svg>"}]},{"check":{"correct_index":3,"explanation":"Use an intentionally unsafe or unhelpful choice as a comparison.","options":["A choice unrelated to safety, health or respect","An answer copied without understanding","A guess with no reason","Use an intentionally unsafe or unhelpful choice as a comparison"],"question":"Which choice best applies this lesson idea about empathy with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nForcing someone to talk is not empathy. Here is a more helpful example: Example: listener nods, paraphrases, asks “Do you want ideas or just listening?”\n\nTRY FIRST\nDescribe why the warned-against choice does not work, then write a safer, kinder or healthier choice with a reason.\n\nFEEDBACK\nHelp should match need; unasked advice can feel dismissive.","explain":"Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Changing the wording without changing the choice does not fix the error. Forcing someone to talk is not empathy. Change the choice or strategy, not just the wording.","title":"Test a misconception"},{"check":{"correct_index":3,"explanation":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example.","options":["A choice unrelated to safety, health or respect","An answer copied without understanding","A guess with no reason","Use the same PDHPE idea in a new place, game or situation, not a copy of the example"],"question":"Which choice best applies this lesson idea about empathy with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nEmpathy role plays practise listening, naming feelings and offering support without taking over. Now choose a different situation to show you can transfer the idea.\n\nTRY FIRST\nDescribe or practise one fresh situation that uses the same skill and write a short reason for your choice.\n\nFEEDBACK\nThe new situation should use the same PDHPE idea as the example, but happen in a different place or with different people.","explain":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to a new situation. Change the choice or strategy, not just the wording.","title":"Transfer to a new situation"}],"title":"Year 4, Week 16, Lesson 2: Empathy role plays","unit_number":4,"unit_title":"Relationships, communication and respect","week":16,"week_in_unit":1,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nExample: listener nods, paraphrases, asks “Do you want ideas or just listening?”\n\nWrite what makes this example safe, healthy or respectful, naming the cues, rules or choices used.","worked_visuals":[{"alt":"Empathy role plays.","caption":"Match help to need.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Listen</text><text x=\"28\" y=\"78\">paraphrase</text><text x=\"358\" y=\"42\">Ask</text><text x=\"358\" y=\"78\">ideas or listening</text></g></svg>"},{"alt":"Support practice.","caption":"Question helped.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Four scenes</text><text x=\"28\" y=\"78\">pass OK</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">force talking</text></g></svg>"}],"year_level":"Year 4"}') WHERE seed_key='s2-pdhpe-y4-w16-l2' AND family_id IS NULL;
